/* ===== Finance settings, approvals and the System Admin Control Centre ===== */
const EV_RE = /\.(pdf|jpe?g|png|docx?|xlsx?|eml|msg)$/i;
const evField = () => `<label class="fld"><span>Evidence file name (mandatory: the approval mail, letter, screenshot or document that supports this)</span><input id="evTxt" placeholder="e.g. approval-mail-18oct.pdf"></label><p class="err" id="evErr" hidden>Name the evidence file (pdf, jpg, png, doc, docx, xls, xlsx, eml or msg). The file itself is kept outside this application.</p>`;
const evRead = () => { const el = document.getElementById('evTxt'); if (!el) return null; const x = (el.value || '').trim(); if (!EV_RE.test(x)) { const e = document.getElementById('evErr'); if (e) e.hidden = false; return false; } return x; };
/* a reason plus an evidence file name; the callback receives both */
function askEvidence(title, desc, onOk) { App.ui._evCb = onOk; askReason(title, desc, (r) => { const cb = App.ui._evCb; App.ui._evCb = null; cb && cb(r, App.ui._evLast || ''); }, evField()); }
function askReason(title, desc, onOk, extra = '') {
  snapForm(); App.ui._reasonCb = onOk;
  modal(title, `<p class="small">${desc}</p>${extra}<label class="fld"><span>Reason for change (recorded in the audit log)</span><textarea id="reasonTxt" rows="3" required placeholder="e.g. Approved in finance committee on 18 Oct"></textarea></label><p class="err" id="reasonErr" hidden>Enter a reason to continue.</p>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="reasonOk">Confirm</button>`);
}
/* form value; when a confirmation modal has replaced the form, values are read from the snapshot taken by askReason / pcRemark */
const v = id => { const el = document.getElementById(id); if (el) return el.type === 'checkbox' ? el.checked : el.value; const S = App.ui._formSnap; return S && id in S ? S[id] : null; };
function snapForm() { const S = {}; document.querySelectorAll('#modal input[id], #modal select[id], #modal textarea[id], #view input[id], #view select[id], #view textarea[id]').forEach(el => { S[el.id] = el.type === 'checkbox' ? el.checked : el.value; }); App.ui._formSnap = S; }
const yes = b => b ? 'Yes' : 'No';
const brName = id => (DATA.branches.find(b => b.id === id) || {}).name || id;

/* ---------- Finance: targets, instalments, calendar, thresholds ---------- */
PAGES.settings = { title: 'Target & Instalment Control', mod: 'settings', render() {
  const c = Store.get('config'), ed = can('settings', 'Edit');
  const dis = ed ? '' : 'disabled';
  const D = D_(), ym = ymOf(D), fz = c.frozen[ym];
  const tgt = card('Monthly collection target', `<div class="form-grid">
    <label class="fld"><span>Default target % of opening outstanding</span><input id="sTP" type="number" min="1" max="100" step="0.5" value="${c.targetPct}" ${dis}></label>
    <label class="fld"><span>Target freeze day of month</span><input id="sFD" type="number" min="1" max="5" value="${c.targetFreezeDay}" ${dis}></label>
    <label class="fld"><span>Report cut-off time</span><input id="sCut" type="time" value="${c.cutoffTime}" ${dis}></label>
    <label class="chk big"><input id="sAdv" type="checkbox" ${c.advanceCounts ? 'checked' : ''} ${dis}> Count advance collection toward target achievement</label><label class="chk big"><input id="sFr" type="checkbox" ${c.freshCounts ? 'checked' : ''} ${dis}> Count collection against dues that fall due during the month</label></div>
    <p class="small muted">Changing the default or a branch-specific percentage creates an approval request (maker-checker). Other changes need a reason and go to the audit log.</p>
    ${ed ? `<div class="btnrow"><button class="btn primary" data-act="saveTarget">Save target rule</button><button class="btn" data-act="branchPct">Request branch-specific %</button></div>` : ''}
    <h4>Branch-specific percentages</h4>${Object.keys(c.branchPct).length ? `<ul>${Object.entries(c.branchPct).map(([b, p]) => `<li>${esc(brName(b))}: <b>${p}%</b></li>`).join('')}</ul>` : '<p class="muted small">None. All branches use the default.</p>'}
    <h4>Target freeze · ${MON[+ym.slice(5) - 1]} ${ym.slice(0, 4)}</h4><p class="small">${fz ? `Frozen by ${esc(fz.by)} on ${tsLabel(fz.at)} for ${Object.keys(fz.t).length} branches.` : 'Not frozen. Targets are recalculated from the opening outstanding until frozen.'}</p>${ed ? `<button class="btn" data-act="${fz ? 'unfreeze' : 'freeze'}">${fz ? 'Unfreeze' : 'Freeze'} ${MON[+ym.slice(5) - 1]} targets</button>` : ''}`);
  const sched = schedFor(App.f.ay), ySel = yearOf(App.f.ay);
  const instT = `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Fee head</th><th>Basis</th><th class="n">% / amount</th><th>Due date</th><th class="n">Grace days</th><th>Applies to</th><th>Status</th>${ed ? '<th></th>' : ''}</tr></thead><tbody>${sched.map((it, k) => `<tr><td>${esc(it.name)}</td><td>${{ py: 'Previous-year balance', pct: '% of net annual fee', fixed: 'Fixed amount' }[it.kind]}</td><td class="n">${it.kind === 'pct' ? it.pct + '%' : it.kind === 'fixed' ? INR(it.amount) : '—'}</td><td>${isoLabel(it.due)}</td><td class="n">${it.grace}</td><td class="wrap">${it.branches === 'all' ? 'All branches' : (it.branches.length + ' branches')}${it.types !== 'all' ? ' · ' + it.types.join(', ') : ''}${it.classes !== 'all' ? ' · classes ' + it.classes.join(', ') : ''}</td><td>${it.active ? pill('Active', 'ok') : pill('Inactive')}</td>${ed ? `<td><button class="btn sm" data-act="editInst" data-k="${k}">Edit</button></td>` : ''}</tr>`).join('')}</tbody></table></div>`;
  const pctSum = sched.filter(i => i.kind === 'pct' && i.active && i.branches === 'all').reduce((a, i) => a + +i.pct, 0);
  const inst = card(`Instalment schedule · AY ${esc(App.f.ay)}`, `<div class="tabs">${yearsList().filter(y => y.status !== 'Closed' || y.code === App.f.ay).map(y => `<button class="tab${y.code === App.f.ay ? ' on' : ''}" data-act="setYear" data-v="${y.code}">${y.code}${y.status === 'Current' ? ' · current' : ''}</button>`).join('')}</div>` + (sched.length ? instT : '<p class="muted small">No instalment schedule for this year yet.</p>') + `<p class="small ${pctSum > 100 ? 'red' : 'muted'}">Percentage heads applying to all branches total ${pctSum}% of the net annual fee.${pctSum !== 100 ? ' Check the schedule: this should normally be 100%.' : ''} Reports add or remove instalment columns from this schedule and the selected date.</p>${ed ? `<div class="btnrow"><button class="btn" data-act="editInst" data-k="new">Add fee head / custom schedule</button>${!isCurYear() && !sched.length ? `<button class="btn" data-act="copySched" data-v="${App.f.ay}">Copy ${CUR_AY} schedule, dates +1 year</button>` : ''}</div>` : ''}`);
  const yrs = yearsList();
  const yearsCard = card('Academic years', `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Academic year</th><th>Start</th><th>End</th><th>Status</th><th class="n">Fee heads</th><th class="n">Target plans</th><th>Source</th>${ed ? '<th></th>' : ''}</tr></thead><tbody>${yrs.map(y => `<tr><td><b>${esc(y.code)}</b></td><td>${isoLabel(y.start)}</td><td>${isoLabel(y.end)}</td><td>${pill(y.status, { Current: 'ok', Upcoming: 'warn' }[y.status] || '')}</td><td class="n">${schedFor(y.code).length}</td><td class="n">${Object.keys(Str.plansFor(y.code)).length}</td><td>${esc(y.source || 'App')}</td>${ed ? `<td class="btnrow"><button class="btn sm" data-act="setYear" data-v="${y.code}">Open</button>${y.status !== 'Current' ? `<button class="btn sm" data-act="editYear" data-k="${y.code}">Edit</button><button class="btn sm" data-act="yearStatus" data-k="${y.code}" data-v="${y.status === 'Closed' ? 'Upcoming' : 'Closed'}">${y.status === 'Closed' ? 'Reopen' : 'Close'}</button>` : ''}</td>` : ''}</tr>`).join('')}</tbody></table></div><p class="small muted">The current year is set by the ERP academic_years master at sync time. Add the next year here to prepare its instalment schedule, targets and capacity before it starts; closed years stay available in Multi-year comparison.</p>${ed ? '<button class="btn primary" data-act="addYear">Add academic year</button>' : ''}`);
  const cd = App.ui.calDraft || { weekOff: c.weekOff.slice(), holidays: c.holidays.slice() };
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const cal = card('Working-days calendar', `<div class="btnrow">${days.map((d, i) => `<label class="chk"><input type="checkbox" id="wo${i}" ${cd.weekOff.includes(i) ? 'checked' : ''} ${dis}> ${d} off</label>`).join('')}</div><h4>Holidays</h4><div class="chips">${cd.holidays.slice().sort().map(h => `<span class="chipx">${isoLabel(h)}${ed ? ` <button aria-label="Remove ${h}" data-act="rmHol" data-k="${h}">✕</button>` : ''}</span>`).join('')}</div>${ed ? `<div class="ctrls"><label class="fld"><span>Add holiday</span><input type="date" id="newHol" min="2026-04-01" max="2027-03-31"></label><button class="btn" data-act="addHol">Add</button><button class="btn primary" data-act="saveCal">Save calendar</button></div>` : ''}<p class="small muted">Used for daily required collection and run-rate projections. The default list is indicative; confirm it against the trust's holiday notice.</p>`);
  const r = c.rag, al = c.alerts;
  const n = (id, lab, val, extra = '') => `<label class="fld"><span>${lab}</span><input id="${id}" type="number" value="${val}" ${dis} ${extra}></label>`;
  const thr = card('Thresholds, risk indicators and alerts', `<div class="form-grid">
    ${n('tZP', 'Zero payer outstanding limit per branch (₹)', c.zpLimitDefault, 'step="50000"')}${n('tOS', 'Outstanding limit (% of fee due)', c.osLimitPct)}
    ${n('rA1', 'Achievement green at ≥ % of expected pace', r.achGreen)}${n('rA2', 'Achievement amber at ≥ % of pace', r.achAmber)}
    ${n('rO1', 'Outstanding risk green at ≤ % due', r.osGreen)}${n('rO2', 'Outstanding risk amber at ≤ % due', r.osAmber)}
    ${n('rZ1', 'Zero payer risk green at ≤ % of outstanding', r.zpGreen)}${n('rZ2', 'Zero payer risk amber at ≤ % of outstanding', r.zpAmber)}
    ${n('aZI', 'Alert: zero payer count increase % (7 days)', al.zpIncreasePct)}${n('aOI', 'Alert: overdue increase % (7 days)', al.overdueIncreasePct)}
    ${n('cR1', 'Alert: cancellation rate above % of gross admissions', c.strength.cancelRatePct)}${n('cR2', 'Alert: exits above % of new admissions', c.strength.cancelVsNewPct)}${n('cR3', 'Alert: repeated cancellations in a class (90 days)', c.strength.classCancels)}${n('cR4', 'Alert: class nearing capacity at %', c.strength.capAlertPct)}
    ${n('aDA', 'Alert: instalment due within days', al.dueApproachDays)}<label class="fld"><span>Alert: no collection posted by</span><input id="aNC" type="time" value="${al.noCollectionBy}" ${dis}></label></div>
    <div class="btnrow">${[['belowDaily', 'Below daily required'], ['missTarget', 'Likely to miss target'], ['osLimit', 'Outstanding above limit'], ['zpLimit', 'Zero payer above limit'], ['syncFail', 'ERP sync failure'], ['recon', 'Reconciliation mismatch']].map(([k, l]) => `<label class="chk"><input type="checkbox" id="al_${k}" ${al[k] ? 'checked' : ''} ${dis}> ${l}</label>`).join('')}<label class="chk"><input type="checkbox" disabled> WhatsApp (future provision)</label></div>
    <div class="form-grid"><label class="fld"><span>Concession treatment</span><input id="tCT" value="${esc(c.concessionTreatment)}" ${dis}></label><label class="fld"><span>Refund treatment</span><input id="tRT" value="${esc(c.refundTreatment)}" ${dis}></label></div>
    ${ed ? '<button class="btn primary" data-act="saveThr">Save thresholds</button>' : ''}<h4>Branch zero payer limit overrides</h4>${Object.keys(c.zpLimit).length ? `<ul>${Object.entries(c.zpLimit).map(([b, x]) => `<li>${esc(brName(b))}: ${INR(x)}${ed ? ` <button class="linkish" data-act="rmZpLim" data-k="${b}">remove</button>` : ''}</li>`).join('')}</ul>` : '<p class="muted small">None.</p>'}${ed ? `<div class="ctrls"><label class="fld grow"><span>Branch</span><select id="zlB">${DATA.branches.map(b => `<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></label><label class="fld"><span>Limit (₹)</span><input id="zlV" type="number" step="50000" value="500000"></label><button class="btn" data-act="addZpLim">Set limit</button></div>` : ''}`);
  return (ed ? '' : '<div class="note">You can view these settings. Only Finance roles can change them.</div>') + `${yearsCard}<div class="grid2">${tgt}${cal}</div>${inst}${thr}`;
} };
function instForm(k) {
  const c = Store.get('config'), y = yearOf(App.f.ay) || {}; const it = k === 'new' ? { key: 'C' + Date.now().toString(36).slice(-4).toUpperCase(), name: '', kind: 'fixed', pct: 0, amount: 0, due: y.start ? E.ds(E.dn(y.start) + 9) : '2026-11-10', grace: 7, active: true, branches: 'all', types: 'all', classes: 'all' } : schedFor(App.f.ay)[+k];
  const types = ['School', 'Junior College', 'Degree College'];
  modal((k === 'new' ? 'Add fee head' : 'Edit ' + it.name) + ' · AY ' + App.f.ay, `<div class="form-grid">
  <label class="fld"><span>Name</span><input id="iN" value="${esc(it.name)}" placeholder="e.g. Transport – Term 2" list="instNames"><datalist id="instNames">${['Previous Year Dues', 'Admission Fee / SRF', 'Instalment 1', 'Instalment 2', 'Instalment 3', 'Instalment 4', 'Annual Charges', 'Transport', 'Hostel'].map(x => `<option>${x}</option>`).join('')}</datalist></label>
  <label class="fld"><span>Basis</span><select id="iK" ${it.kind === 'py' ? 'disabled' : ''}>${[['pct', '% of net annual fee'], ['fixed', 'Fixed amount per student'], ['py', 'Previous-year balance']].map(([a, b]) => `<option value="${a}" ${it.kind === a ? 'selected' : ''} ${a === 'py' && it.kind !== 'py' ? 'disabled' : ''}>${b}</option>`).join('')}</select></label>
  <label class="fld"><span>Percentage</span><input id="iP" type="number" step="0.5" value="${it.pct || 0}"></label><label class="fld"><span>Fixed amount (₹)</span><input id="iA" type="number" step="100" value="${it.amount || 0}"></label>
  <label class="fld"><span>Due date</span><input id="iD" type="date" value="${it.due}"></label><label class="fld"><span>Grace period (days)</span><input id="iG" type="number" min="0" value="${it.grace}"></label>
  <label class="fld"><span>School types</span><select id="iT" multiple size="3">${types.map(t => `<option ${it.types === 'all' || it.types.includes(t) ? 'selected' : ''}>${t}</option>`).join('')}</select></label>
  <label class="fld"><span>Branches (none selected = all)</span><select id="iB" multiple size="5">${DATA.branches.map(b => `<option value="${b.id}" ${it.branches !== 'all' && it.branches.includes(b.id) ? 'selected' : ''}>${esc(b.name)}</option>`).join('')}</select></label>
  <label class="fld"><span>Classes (comma separated, blank = all)</span><input id="iC" value="${it.classes === 'all' ? '' : esc(it.classes.join(', '))}"></label>
  <label class="chk big"><input type="checkbox" id="iX" ${it.active ? 'checked' : ''}> Active</label></div><p class="small muted">Student groups and fee categories map to classes and school types in this demo. Changes re-run the instalment allocation for every report.</p>`,
    `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="saveInst" data-k="${k}">Save</button>`, true);
}

/* ---------- Approvals (maker-checker) ---------- */
PAGES.approvals = { title: 'Approvals & Adjustments', mod: 'approvals', render() {
  const show = App.ui.apShow || 'Pending';
  const L = Store.list('approvals').filter(a => show === 'All' || a.status === show);
  const me = App.user.id, canAp = can('approvals', 'Approve') || can('cancel', 'Approve');
  const desc = a => a.type === 'exit' ? `${a.payload.exitType}: ${a.payload.studentName} (${a.payload.adm}) from ${isoLabel(a.payload.date)} · ${a.payload.reason} · refund ${INR(a.payload.refund)}` : a.type === 'adjustment' ? `${a.payload.studentName} (${a.payload.adm}) · ${a.payload.amount < 0 ? 'reduce dues by' : 'add dues of'} ${INR(Math.abs(a.payload.amount))} from ${isoLabel(a.payload.date)}` : a.type === 'targetPct' ? `Default target ${a.payload.from}% → ${a.payload.to}%` : `${brName(a.payload.branch)}: target ${a.payload.from}% → ${a.payload.to}%`;
  const t = table('ap', [{ h: 'Requested', k: a => tsLabel(a.ts), t: 'text', x: a => a.ts }, { h: 'Type', k: a => ({ adjustment: 'Financial adjustment', targetPct: 'Target % change', branchPct: 'Branch target %', exit: 'Cancellation / withdrawal' }[a.type]), t: 'text' }, { h: 'Change', k: a => desc(a), t: 'text', cls: 'wrap' }, { h: 'Original value', k: a => a.payload.original != null ? INR(a.payload.original) : a.payload.from != null ? a.payload.from + '%' : '', t: 'text' }, { h: 'Revised value', k: a => a.payload.revised != null ? INR(a.payload.revised) : a.payload.to != null ? a.payload.to + '%' : '', t: 'text' }, { h: 'Reason', k: a => a.reason, t: 'text', cls: 'wrap' }, { h: 'Attachment', k: a => a.attachment || '—', t: 'text' }, { h: 'Requester', k: a => a.requester, t: 'text' }, { h: 'Status', k: a => a.status === 'Pending' ? (canAp && a.requesterId !== me ? `<button class="btn sm primary" data-act="approve" data-k="${a.id}">Approve</button> <button class="btn sm" data-act="reject" data-k="${a.id}">Reject</button>` : pill(a.requesterId === me ? 'Pending – needs another approver' : 'Pending', 'warn')) : pill(`${a.status} by ${a.approver}`, a.status === 'Approved' ? 'ok' : 'bad'), t: 'html', x: a => a.status }], L, { title: 'Approval requests', empty: show === 'Pending' ? 'No pending requests.' : 'No requests.' });
  const tabs = `<div class="tabs">${['Pending', 'Approved', 'Rejected', 'All'].map(k => `<button class="tab${k === show ? ' on' : ''}" data-act="ui" data-k="apShow" data-v="${k}">${k}</button>`).join('')}</div>`;
  return `<div class="note">ERP-synced financial figures cannot be edited. Permitted corrections are raised here, need a reason and a supporting attachment, and take effect only after a different authorised user approves them.</div>${card('Requests', tabs + t, { right: can('approvals', 'Add') ? '<button class="btn primary sm" data-act="newAdj" data-k="">Add adjustment</button>' : '' })}`;
} };
function adjForm(sid) {
  const s = sid !== '' && sid != null ? DATA.students[+sid] : null;
  modal('Request financial adjustment', `<div class="form-grid"><label class="fld"><span>Student admission no.</span><input id="aAdm" value="${s ? esc(s.adm) : ''}" placeholder="e.g. B06-26014"></label>
  <label class="fld"><span>Adjustment</span><select id="aDir"><option value="-1">Reduce dues (waiver / correction)</option><option value="1">Add dues (missed charge)</option></select></label>
  <label class="fld"><span>Amount (₹)</span><input id="aAmt" type="number" min="1" step="1"></label><label class="fld"><span>Effective date</span><input id="aDate" type="date" value="${App.f.date}"></label>
  <label class="fld"><span>Supporting attachment</span><input id="aFile" type="file"></label></div>
  <label class="fld"><span>Reason</span><textarea id="aReason" rows="3"></textarea></label><p class="err" id="aErr" hidden></p>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="submitAdj">Submit for approval</button>`, true);
}

/* ---------- System Admin Control Centre ---------- */
PAGES.admin_home = { title: 'System Admin Control Centre', mod: 'admin_home', render() {
  const U = users(), map = Store.get('mappings');
  const st = s => U.filter(u => u.status === s).length;
  const roleCount = ROLES.map(r => [r, U.filter(u => u.role === r).length]).filter(x => x[1]);
  const noPr = DATA.branches.filter(b => !U.some(u => u.role === 'Principal' && u.status === 'Active' && u.branch === b.id && map.some(m => m.user === u.id && activeOn(m, ACCESS_DATE))));
  const noDir = DATA.branches.filter(b => !headOf('zd', b));
  const dirs = U.filter(u => u.role === 'Zonal Director' && u.status === 'Active').map(u => [u, DATA.branches.filter(b => (headOf('zd', b) || {}).id === u.id).length]);
  const sync = Store.get('sync'), log = Store.list('emaillog'), ed = Store.get('emaildist');
  const failed = log.filter(x => /^Failed/.test(x.status)).length;
  const exN = Recon.list(TODAY).filter(x => !Store.get('resolved')[x.id]).length;
  const k = (l, v, s = '', cls = '') => `<div class="kpi"><div class="kpi-l">${l}</div><div class="kpi-v ${cls}">${v}</div><div class="kpi-s">${s}</div></div>`;
  const pend = Store.list('approvals').filter(a => a.status === 'Pending').length;
  return `<div class="kpis">${k('Active users', st('Active'), `of ${U.length} accounts`)}${k('Pending activation', st('Pending Activation'), 'awaiting first sign-in', st('Pending Activation') ? 'amber' : '')}${k('Locked / inactive', st('Locked') + st('Inactive') + st('Resigned'), `${st('Locked')} locked · ${st('Inactive')} inactive · ${st('Resigned')} resigned`)}${k('ERP sync', esc(sync.runs[0].status), 'Last success ' + tsLabel(sync.lastSuccess), sync.runs[0].status === 'Success' ? '' : 'red')}${k('Failed emails', failed, `${ed.lists.filter(l => l.active && l.freq === 'Daily').length} daily schedules due today`, failed ? 'red' : '')}${k('Open exceptions', exN, `${pend} pending approvals`, exN ? 'amber' : '')}</div>
  <div class="grid3">${card('Users by role', `<table class="tbl mini"><tbody>${roleCount.map(([r, n]) => `<tr><td>${esc(r)}</td><td class="n">${n}</td></tr>`).join('')}</tbody></table>`)}
  ${card('Mapping gaps', `<h4>Branches without an active Principal (${noPr.length})</h4>${noPr.length ? `<ul class="small">${noPr.map(b => `<li>${esc(b.name)}</li>`).join('')}</ul>` : '<p class="small muted">None.</p>'}<h4>Branches without a Zonal Director (${noDir.length})</h4>${noDir.length ? `<ul class="small">${noDir.map(b => `<li>${esc(b.name)}</li>`).join('')}</ul>` : '<p class="small muted">None.</p>'}<button class="btn sm" data-act="go" data-r="admin_mapping">Open mapping</button>`)}
  ${card('Zonal Directors and their branches', `<table class="tbl mini"><tbody>${dirs.map(([u, n]) => `<tr><td>${esc(u.name.replace(' (demo)', '').replace(/^(Branch )?Director – /, ''))}</td><td class="n">${n}</td></tr>`).join('')}</tbody></table>`)}</div>
  <div class="grid2">${card('ERP sync runs', `<table class="tbl mini"><thead><tr><th>Run</th><th>Status</th><th>Detail</th></tr></thead><tbody>${sync.runs.slice(0, 6).map(r => `<tr><td>${tsLabel(r.at)}</td><td>${pill(r.retried ? r.status + ' · retried' : r.status, r.status === 'Success' || r.retried ? 'ok' : 'bad')}</td><td class="wrap small">${esc(r.error || r.by)}</td></tr>`).join('')}</tbody></table>`, { right: '<button class="btn sm" data-act="go" data-r="admin_sync">Sync centre</button>' })}
  ${card('Recent configuration changes and audit activity', `<table class="tbl mini"><tbody>${Store.list('audit').slice(0, 8).map(a => `<tr><td class="small">${tsLabel(a.ts)}</td><td class="small">${esc(a.user)}</td><td class="small wrap">${esc(a.module)} · ${esc(a.action)}</td></tr>`).join('') || '<tr><td>No activity recorded yet.</td></tr>'}</tbody></table>`, { right: '<button class="btn sm" data-act="go" data-r="audit">Audit log</button>' })}</div>`;
} };

